import{_ as i,o as a,c as d,a3 as n,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const b=JSON.parse('{"title":"Reports verwenden und verwalten","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/reportverwaltung.md","filePath":"reporting/reportverwaltung.md"}'),s={name:"reporting/reportverwaltung.md"};function o(l,r,u,h,c,g){return a(),d("div",null,[...r[0]||(r[0]=[n('<h1 id="reports-verwenden-und-verwalten" tabindex="-1">Reports verwenden und verwalten <a class="header-anchor" href="#reports-verwenden-und-verwalten" aria-label="Permalink to &quot;Reports verwenden und verwalten&quot;">​</a></h1><p>Mit der Reportverwaltung richten Sie vorhandene Reports ein und erzeugen daraus Ausgaben mit den Daten Ihrer Schule. Dieser Einstieg führt Sie vom Einfügen eines Reports bis zur Kontrolle der Ausgabe. Wenn der Report bereits eingerichtet ist, beginnen Sie bei Schritt 3.</p><h2 id="was-mochten-sie-tun" tabindex="-1">Was möchten Sie tun? <a class="header-anchor" href="#was-mochten-sie-tun" aria-label="Permalink to &quot;Was möchten Sie tun?&quot;">​</a></h2><ul><li>Einen neuen Report verwenden: Folgen Sie dem <a href="#einen-report-einrichten-und-verwenden">Arbeitsablauf</a>.</li><li>Daten eines früheren Halbjahres ausgeben: Lesen Sie <a href="/reporting/reportverwaltung/daten-aus-zurueckliegenden-abschnitten-drucken.html">Daten aus zurückliegenden Abschnitten drucken</a>.</li><li>Einen häufig benötigten Report schneller öffnen: Nutzen Sie den <a href="/reporting/reportverwaltung/reports-ueber-den-schnellzugriff-aufrufen.html">Schnellzugriff</a>.</li><li>Eine Schaltfläche nachschlagen: Öffnen Sie die Beschreibung des <a href="/reporting/reportverwaltung/menueband-reportverwaltung.html">Menübands der Reportverwaltung</a>.</li><li>Einen Report selbst gestalten: Wechseln Sie zu <a href="/reporting/reportdesigner.html">Reports erstellen und anpassen</a>.</li></ul><h2 id="einen-report-einrichten-und-verwenden" tabindex="-1">Einen Report einrichten und verwenden <a class="header-anchor" href="#einen-report-einrichten-und-verwenden" aria-label="Permalink to &quot;Einen Report einrichten und verwenden&quot;">​</a></h2><h3 id="_1-den-passenden-ordner-vorbereiten" tabindex="-1">1. Den passenden Ordner vorbereiten <a class="header-anchor" href="#_1-den-passenden-ordner-vorbereiten" aria-label="Permalink to &quot;1. Den passenden Ordner vorbereiten&quot;">​</a></h3><p>Die Reportverwaltung bildet die Ordnerstruktur unter <code>Schild-Reports</code> im SchILD-Arbeitsverzeichnis ab. Wählen Sie einen passenden Unterordner oder legen Sie einen eigenen an, etwa für die Sekundarstufe I.</p>',7),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),t("Wichtig – Arbeitsverzeichnis im Netzwerk")]),e("p",null,"Bei einer Netzwerkinstallation verwenden Sie das Arbeitsverzeichnis im Netzwerk. Der konkrete Pfad kann von den Beispielen in der Dokumentation abweichen.")],-1),n('<p>Beachten Sie die besonderen Ordner <code>Subreports</code> und <code>Header_Footer</code>. Für Zeugnisformulare empfiehlt sich eine Ablage nach Schuljahr und Halbjahr, damit die ursprünglichen Formulare für spätere Nachdrucke erhalten bleiben.</p><p>Die Einzelheiten erläutert <a href="/reporting/reportverwaltung/die-ordnerstruktur-der-reportverwaltung.html">Die Ordnerstruktur der Reportverwaltung</a>.</p><h3 id="_2-den-report-einfugen" tabindex="-1">2. Den Report einfügen <a class="header-anchor" href="#_2-den-report-einfugen" aria-label="Permalink to &quot;2. Den Report einfügen&quot;">​</a></h3><p>Entpacken Sie das Reportarchiv in den gewählten Ordner. Die eigentliche Reportvorlage hat die Erweiterung <code>.rtm</code>; eine zusätzlich enthaltene PDF-Datei zeigt ein bereits erzeugtes Beispiel.</p><p>Ist die Reportverwaltung währenddessen geöffnet, klicken Sie auf <strong>Verzeichnisbaum aktualisieren</strong>. Der eingefügte Report erscheint anschließend im entsprechenden Ordner.</p><p>Die bebilderte Anleitung <a href="/reporting/reportverwaltung/reports-in-die-reportverwaltung-einfuegen.html">Reports in die Reportverwaltung einfügen</a> zeigt Download, Entpacken und Aufruf an einem Beispiel. Für ganze Sammlungen verwenden Sie die Anleitungen zu <a href="/reporting/basisreports/basisreportsammlung-herunterladen-und-aktualisieren.html">Basisreports</a> oder <a href="/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html">Zeugnisformularen</a>.</p><h3 id="_3-lernabschnitt-und-personenkreis-wahlen" tabindex="-1">3. Lernabschnitt und Personenkreis wählen <a class="header-anchor" href="#_3-lernabschnitt-und-personenkreis-wahlen" aria-label="Permalink to &quot;3. Lernabschnitt und Personenkreis wählen&quot;">​</a></h3><p>Standardmäßig werden Daten des aktuellen Abschnitts verwendet. Benötigen Sie eine Ausgabe für ein früheres Halbjahr, wählen Sie vor dem Aufruf den passenden Eintrag unter <strong>Schuljahr/Abschnitt</strong>. Die Anleitung <a href="/reporting/reportverwaltung/daten-aus-zurueckliegenden-abschnitten-drucken.html">Daten aus zurückliegenden Abschnitten drucken</a> zeigt die Auswahl.</p><p>Öffnen Sie den Report mit einem Doppelklick. Beim Aufruf wählen Sie, ob die Ausgabe für die ausgewählte Person, die markierten Personen oder die ganze Gruppe erzeugt werden soll.</p>',9),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),t("Wichtig – Nach dem Druck zurückstellen")]),e("p",null,"Wenn Sie einen früheren Abschnitt gewählt haben, stellen Sie danach wieder den aktuellen Abschnitt ein. Sonst können auch die folgenden Reports mit Daten des falschen Abschnitts erzeugt werden.")],-1),n('<h3 id="_4-die-ausgabe-in-der-vorschau-kontrollieren" tabindex="-1">4. Die Ausgabe in der Vorschau kontrollieren <a class="header-anchor" href="#_4-die-ausgabe-in-der-vorschau-kontrollieren" aria-label="Permalink to &quot;4. Die Ausgabe in der Vorschau kontrollieren&quot;">​</a></h3><p>Je nach Report erscheinen zusätzliche Rückfragen. Prüfen Sie deren Wirkung in der Vorschau. Im Beispiel der Einfügeanleitung betrifft dies die Formatierung von Bemerkungen, Arbeits- und Sozialverhalten sowie außerunterrichtlichem Engagement; andere Reports können andere Rückfragen stellen.</p><p>Kontrollieren Sie vor der weiteren Ausgabe, ob Lernabschnitt, Personenkreis und Darstellung zum gewünschten Ergebnis passen. Entscheiden Sie anschließend, ob der Report verwendet werden kann oder angepasst werden muss.</p><h2 id="haufig-benotigte-erganzungen" tabindex="-1">Häufig benötigte Ergänzungen <a class="header-anchor" href="#haufig-benotigte-erganzungen" aria-label="Permalink to &quot;Häufig benötigte Ergänzungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Reports in einem schwebenden Fenster bereitstellen</td><td><a href="/reporting/reportverwaltung/reports-ueber-den-schnellzugriff-aufrufen.html">Reports über den Schnellzugriff aufrufen</a></td></tr><tr><td>Stammblatt oder Schulbescheinigung direkt öffnen</td><td><a href="/reporting/serienbriefe/direkter-zugriff-auf-das-schuelerstammblatt-und-die-schulbescheinigung.html">Direkter Zugriff auf das Schülerstammblatt und die Schulbescheinigung</a></td></tr><tr><td>Erzeugte Dokumente archivieren</td><td><a href="/reporting/zeugnisformulare/dokumentenverwaltung-und-zeugnisarchivierung.html">Dokumentenverwaltung und Zeugnisarchivierung</a></td></tr><tr><td>Den Ablageort der Dokumente ändern</td><td><a href="/reporting/reportdesigner/verzeichnis-der-dokumentenverwaltung-aendern-tutorial.html">Verzeichnis der Dokumentenverwaltung ändern</a></td></tr><tr><td>Einen Report per E-Mail versenden</td><td><a href="/reporting/reportverwaltung/einen-report-per-e-mail-versenden-und-teilen.html">Einen Report per E-Mail versenden und teilen</a></td></tr><tr><td>Schülerindividuelle Reports gesammelt per E-Mail versenden</td><td><a href="/reporting/reportdesigner/serien-e-mail-versand.html">Serien-E-Mail-Versand</a></td></tr></tbody></table><h2 id="wenn-der-report-nicht-wie-erwartet-erscheint" tabindex="-1">Wenn der Report nicht wie erwartet erscheint <a class="header-anchor" href="#wenn-der-report-nicht-wie-erwartet-erscheint" aria-label="Permalink to &quot;Wenn der Report nicht wie erwartet erscheint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Beobachtung</th><th>Nächster Schritt</th></tr></thead><tbody><tr><td>Eine im Windows-Explorer eingefügte Reportdatei fehlt in der geöffneten Reportverwaltung.</td><td><strong>Verzeichnisbaum aktualisieren</strong> ausführen; Ablage unter dem tatsächlich verwendeten Arbeitsverzeichnis kontrollieren.</td></tr><tr><td>Eine geänderte Fachbezeichnung erscheint noch mit dem alten Stand.</td><td><strong>Abfragen aktualisieren</strong> verwenden. Einige Katalogdaten werden beim Start in die Reportumgebung geladen.</td></tr><tr><td>Ein neu verfügbarer Windows-Drucker fehlt in der Auswahl.</td><td><strong>Druckerliste aktualisieren</strong> ausführen.</td></tr></tbody></table><p>Diese Funktionen sind im <a href="/reporting/reportverwaltung/menueband-reportverwaltung.html">Menüband der Reportverwaltung</a> beschrieben.</p>',8)])])}const f=i(s,[["render",o]]);export{b as __pageData,f as default};
